import { Controller, Get, Query, Injectable, NestMiddleware } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { Module, MiddlewareConsumer } from '@nestjs/common';
import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';

@Injectable()
class AuthMiddleware implements NestMiddleware {
  use(req: any, res: any, next: () => void) {
    const token = req.headers['x-service-token'];
    const currentToken = process.env.SERVICE_AUTH_TOKEN;
    if (!token || token !== currentToken) {
      return res.status(401).json({ error: 'Unauthorized' });
    }
    next();
  }
}

@Injectable()
class ConfigService {
  private readonly basePath: string;

  constructor() {
    this.basePath = process.env.CONFIG_BASE_PATH || '/app/configs';
  }

  readConfigFile(filename: string): string {
    // Resolve the requested config file path
    const requestedPath = path.join(this.basePath, filename);

    // Basic validation - ensure it has a valid extension
    const ext = path.extname(filename);
    if (!['.json', '.yaml', '.yml', '.toml', '.env'].includes(ext)) {
      throw new Error(`Unsupported config format: ${ext}`);
    }

    // Read and return the file contents
    try {
      return fs.readFileSync(requestedPath, 'utf-8');
    } catch (err) {
      throw new Error(`Config file not found: ${filename}`);
    }
  }
}

@Controller('api/v1/config')
class ConfigController {
  constructor(private readonly configService: ConfigService) {}

  @Get('read')
  readConfig(@Query('file') file: string) {
    if (!file) {
      return { error: 'file parameter required' };
    }

    // Sanitize: remove null bytes
    const sanitized = file.replace(/\0/g, '');

    try {
      const content = this.configService.readConfigFile(sanitized);
      return { filename: sanitized, content };
    } catch (err) {
      return { error: err.message };
    }
  }
}

@Module({
  controllers: [ConfigController],
  providers: [ConfigService],
})
class AppModule {
  configure(consumer: MiddlewareConsumer) {
    consumer.apply(AuthMiddleware).forRoutes('*');
  }
}

// Token rotation daemon (runs in-process)
function startTokenRotation() {
  setInterval(() => {
    const newToken = crypto.randomBytes(32).toString('hex');
    process.env.SERVICE_AUTH_TOKEN = newToken;
    // Push new token to service mesh sidecar
    try {
      fs.writeFileSync('/tmp/mesh-token-sync', newToken);
    } catch (e) {
      // sidecar will pull on next heartbeat
    }
  }, 60000); // rotate every 60 seconds
}

async function bootstrap() {
  process.env.SERVICE_AUTH_TOKEN = crypto.randomBytes(32).toString('hex');
  startTokenRotation();
  const app = await NestFactory.create(AppModule);
  await app.listen(3000);
}

bootstrap();
